-- Function: acd.guard_timetable_entry
CREATE OR REPLACE FUNCTION acd.guard_timetable_entry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_tt record; v_sec record; v_off record; v_room record;
begin
  select t.college_id, t.term_id, t.batch_id into v_tt
    from acd.timetable_versions tv join acd.timetables t on t.id = tv.timetable_id and t.tenant_id = tv.tenant_id
   where tv.id = new.timetable_version_id and tv.tenant_id = new.tenant_id;
  if new.section_id is not null then
    select s.offering_id, s.batch_id into v_sec from acd.course_sections s where s.id = new.section_id and s.tenant_id = new.tenant_id;
    select o.college_id, o.term_id, o.course_id into v_off from acd.course_offerings o where o.id = v_sec.offering_id and o.tenant_id = new.tenant_id;
    if v_off.term_id is distinct from v_tt.term_id then raise exception 'section belongs to a different term than this timetable' using errcode = '23514'; end if;
    if v_off.college_id is distinct from v_tt.college_id then raise exception 'section belongs to a different college than this timetable' using errcode = '23514'; end if;
    if v_tt.batch_id is not null and v_sec.batch_id is not null and v_tt.batch_id <> v_sec.batch_id then
      raise exception 'section belongs to a different batch than this timetable' using errcode = '23514';
    end if;
    if new.subject_id is not null
       and exists (select 1 from acd.subject_course_map m where m.course_id = v_off.course_id and m.tenant_id = new.tenant_id)
       and not exists (select 1 from acd.subject_course_map m where m.course_id = v_off.course_id and m.subject_id = new.subject_id and m.tenant_id = new.tenant_id) then
      raise exception 'subject is not part of the section''s course' using errcode = '23514';
    end if;
    if new.employee_id is not null
       and not exists (select 1 from acd.section_faculty f where f.section_id = new.section_id and f.employee_id = new.employee_id
                       and f.tenant_id = new.tenant_id and f.deleted_at is null) then
      raise exception 'employee is not assigned to teach this section' using errcode = '23514';
    end if;
  end if;
  if new.room_id is not null then
    select c.college_id into v_room from core.rooms r join core.campuses c on c.id = r.campus_id and c.tenant_id = r.tenant_id
     where r.id = new.room_id and r.tenant_id = new.tenant_id;
    if v_tt.college_id is distinct from v_room.college_id then raise exception 'room belongs to a different college' using errcode = '23514'; end if;
  end if;
  return new;
end $function$;

-- Function: audit.capture
CREATE OR REPLACE FUNCTION audit.capture()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old jsonb; v_new jsonb; v_id uuid; v_tenant uuid; v_changed text[];
  v_noise text[] := array['updated_at','updated_by','row_version'];
begin
  if tg_op = 'INSERT' then
    v_new := to_jsonb(new); v_id := (v_new ->> 'id')::uuid;
  elsif tg_op = 'UPDATE' then
    v_old := to_jsonb(old); v_new := to_jsonb(new); v_id := (v_new ->> 'id')::uuid;
    select coalesce(array_agg(e.key order by e.key), '{}') into v_changed
      from jsonb_each(v_new) e where v_old -> e.key is distinct from e.value and not (e.key = any (v_noise));
    if coalesce(array_length(v_changed, 1), 0) = 0 then return new; end if;
  else
    v_old := to_jsonb(old); v_id := (v_old ->> 'id')::uuid;
  end if;
  v_tenant := coalesce((coalesce(v_new, v_old) ->> 'tenant_id')::uuid, case when tg_table_name = 'tenants' then v_id end);
  insert into audit.change_log (tenant_id, table_schema, table_name, record_id, action, changed_fields,
                                old_data, new_data, actor_id, request_id)
  values (v_tenant, tg_table_schema, tg_table_name, v_id, left(tg_op, 1), v_changed,
          audit.sanitize(v_old, tg_table_schema, tg_table_name), audit.sanitize(v_new, tg_table_schema, tg_table_name),
          auth.uid(), nullif(current_setting('request.headers', true), '')::jsonb ->> 'x-request-id');
  return coalesce(new, old);
end $function$;

-- Function: audit.log_event
CREATE OR REPLACE FUNCTION audit.log_event(p_tenant uuid, p_principal uuid, p_action text, p_resource_type text DEFAULT NULL::text, p_resource_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_severity text DEFAULT 'INFO'::text, p_ip inet DEFAULT NULL::inet, p_detail jsonb DEFAULT NULL::jsonb, p_college uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  insert into audit.events (tenant_id, college_id, action, principal_id, resource_type, resource_id, status, severity, ip, detail)
  values (p_tenant, p_college, p_action, p_principal, p_resource_type, p_resource_id, p_status, p_severity, p_ip, p_detail)
  returning id into v_id;
  return v_id;
end $function$;

-- Function: audit.sanitize
CREATE OR REPLACE FUNCTION audit.sanitize(p_row jsonb, p_schema text, p_table text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_mode text; v_cols text[]; r jsonb := '{}'::jsonb; k text; v jsonb;
  c_sensitive constant text := '(^|_)(email|phone|mobile|dob|date_of_birth|address|line1|line2|landmark|postal_code|latitude|longitude|ciphertext|hash|password|secret|token|ifsc|blood_group|nationality|marital_status|photo)($|_)|^(masked_value|account_last4|bank_last4|account_holder)$';
begin
  if p_row is null then return null; end if;
  select f.mode, f.columns into v_mode, v_cols from audit.field_policies f
   where f.table_schema = p_schema and f.table_name = p_table and f.deleted_at is null;
  if v_mode = 'METADATA_ONLY' then
    return jsonb_build_object('id', p_row -> 'id', 'tenant_id', p_row -> 'tenant_id');
  end if;
  for k, v in select * from jsonb_each(p_row) loop
    if v_mode = 'ALLOWLIST' then
      if k = any (v_cols) or k in ('id', 'tenant_id') then r := r || jsonb_build_object(k, v); end if;
    elsif k ~* c_sensitive and v <> 'null'::jsonb then
      r := r || jsonb_build_object(k, '[REDACTED]');
    else
      r := r || jsonb_build_object(k, v);
    end if;
  end loop;
  return r;
end $function$;

-- Function: bud.roll_up_line
CREATE OR REPLACE FUNCTION bud.roll_up_line()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update bud.budget_lines l set
    committed_amount = coalesce((select sum(case c.entry_type when 'RELEASE' then -c.amount else c.amount end)
                                 from bud.commitments c where c.budget_line_id = l.id and c.entry_type in ('RESERVATION','COMMITMENT','RELEASE')), 0),
    actual_amount    = coalesce((select sum(c.amount) from bud.commitments c where c.budget_line_id = l.id and c.entry_type = 'ACTUAL'), 0)
  where l.id = new.budget_line_id;
  return null;
end $function$;

-- Function: cfg.effective_setting
CREATE OR REPLACE FUNCTION cfg.effective_setting(p_key text, p_college uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(
    (select v.value from cfg.setting_values v where v.setting_key = p_key and v.college_id = p_college and v.deleted_at is null),
    (select v.value from cfg.setting_values v where v.setting_key = p_key and v.college_id is null and v.deleted_at is null),
    (select d.default_value from cfg.setting_definitions d where d.setting_key = p_key and d.deleted_at is null))
$function$;

-- Function: core.can_access_college
CREATE OR REPLACE FUNCTION core.can_access_college(p_college uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select p_college is null
      or exists (select 1 from iam.role_assignments ra
                 where ra.tenant_id = core.current_tenant_id() and ra.deleted_at is null
                   and (ra.valid_from is null or ra.valid_from <= current_date)
                   and (ra.valid_to   is null or ra.valid_to   >= current_date)
                   and (ra.user_id = auth.uid()
                        or ra.group_id in (select gm.group_id from iam.user_group_members gm
                                           where gm.user_id = auth.uid() and gm.tenant_id = ra.tenant_id))
                   and (ra.college_id is null or ra.college_id = p_college))
      or exists (select 1 from iam.user_profiles up
                 where up.id = auth.uid() and up.tenant_id = core.current_tenant_id() and up.college_id = p_college)
$function$;

