-- Function: iam.sc_bud_budgets
CREATE OR REPLACE FUNCTION iam.sc_bud_budgets(p_perm text, p_write boolean DEFAULT false)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
