-- Function: iam.seed_system_roles
CREATE OR REPLACE FUNCTION iam.seed_system_roles(p_tenant uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into iam.roles (tenant_id, code, name, description, is_system)
  select p_tenant, t.code, t.name, t.scope_note, true from iam.role_templates t where t.deleted_at is null
  on conflict do nothing;
  insert into iam.role_permissions (tenant_id, role_id, permission_id)
  select p_tenant, r.id, p.id
    from iam.role_template_permissions tp
    join iam.roles r on r.tenant_id = p_tenant and r.code = tp.role_code and r.college_id is null and r.is_system and r.deleted_at is null
    join iam.permissions p on p.code = tp.permission_code and p.deleted_at is null
   where tp.deleted_at is null
  on conflict do nothing;
  delete from iam.role_permissions rp using iam.roles r, iam.permissions p
   where rp.tenant_id = p_tenant and rp.role_id = r.id and r.tenant_id = p_tenant and r.is_system and r.college_id is null and p.id = rp.permission_id
     and not exists (select 1 from iam.role_template_permissions tp where tp.role_code = r.code and tp.permission_code = p.code and tp.deleted_at is null);
end $function$;

-- Function: sys.enable_rls_on_new_tables
CREATE OR REPLACE FUNCTION sys.enable_rls_on_new_tables()
 RETURNS event_trigger
 LANGUAGE plpgsql
AS $function$
declare r record;
begin
  for r in
    select objid::regclass as tbl
    from pg_event_trigger_ddl_commands()
    where command_tag = 'CREATE TABLE'
      and schema_name in ('audit','cam','hrm','lms')
  loop
    execute format('alter table %s enable row level security', r.tbl);
  end loop;
end $function$;

-- Function: sys.ensure_partitions
CREATE OR REPLACE FUNCTION sys.ensure_partitions(p_months_ahead integer DEFAULT 3)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t text; m date; nm text; i int;
begin
  foreach t in array array['audit.change_log', 'audit.events', 'audit.access_events', 'lms.progress_events', 'hrm.attendance_punches', 'cam.delivery_events'] loop
    for i in 0..p_months_ahead loop
      m  := (date_trunc('month', now() at time zone 'UTC') + make_interval(months => i))::date;
      nm := format('%s_p%s', t, to_char(m, 'YYYYMM'));
      if to_regclass(nm) is null then
        execute format('create table %s partition of %s for values from (%L) to (%L)', nm, t,
                       (m::timestamp at time zone 'UTC'), ((m + interval '1 month')::timestamp at time zone 'UTC'));
        execute format('revoke all on %s from anon, authenticated', nm);   -- RLS lives on the parent; never expose partitions directly
      end if;
    end loop;
  end loop;
end $function$;

-- Function: sys.forbid_mutation
CREATE OR REPLACE FUNCTION sys.forbid_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  raise exception 'table %.% is append-only (immutable)', tg_table_schema, tg_table_name using errcode = 'restrict_violation';
end $function$;

-- Function: sys.touch_row
CREATE OR REPLACE FUNCTION sys.touch_row()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at := now();
  new.updated_by := auth.uid();
  new.row_version := coalesce(old.row_version, 0) + 1;   -- optimistic concurrency: client sends row_version in WHERE
  return new;
end $function$;

-- Function: sys.touch_row_lean
CREATE OR REPLACE FUNCTION sys.touch_row_lean()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin new.updated_at := now(); return new; end $function$;

