    event_date date NOT NULL,
    from_value jsonb,
    to_value jsonb,
    reason text,
    workflow_instance_id uuid,
    created_at timestamptz DEFAULT now() NOT NULL,
    created_by uuid DEFAULT auth.uid()
);

