CREATE POLICY "assessment_components_delete" ON acd.assessment_components AS PERMISSIVE FOR DELETE TO authenticated USING (((tenant_id = ( SELECT core.current_tenant_id() AS current_tenant_id)) AND (( SELECT iam.perm_all('acd09.manage'::text) AS perm_all) OR (structure_id IN ( SELECT iam.sc_acd_assessment_structures('acd09.manage'::text, true) AS sc_acd_assessment_structures)))));
CREATE POLICY "assessment_components_insert" ON acd.assessment_components AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((tenant_id = ( SELECT core.current_tenant_id() AS current_tenant_id)) AND (( SELECT iam.perm_all('acd09.write'::text) AS perm_all) OR (structure_id IN ( SELECT iam.sc_acd_assessment_structures('acd09.write'::text, true) AS sc_acd_assessment_structures)))));
